import dkmeansInitRandomPartition = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const k = 3;
	const M = 5;
	const N = 2;

	const out = new Float64Array( k * N );
	const x = new Float64Array( M * N );
	const W = new Int32Array( k );
	const options = {
		'seed': 1234
	};

	dkmeansInitRandomPartition( 'row-major', M, N, k, x, N, out, N, W, 1 ); // $ExpectType Float64Array
	dkmeansInitRandomPartition( 'row-major', M, N, k, x, N, out, N, W, 1, options ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a layout...
{
	const k = 3;
	const M = 5;
	const N = 2;

	const out = new Float64Array( k * N );
	const x = new Float64Array( M * N );
	const W = new Int32Array( k );

	dkmeansInitRandomPartition( 5, M, N, k, x, N, out, N, W, 1 ); // $ExpectError
	dkmeansInitRandomPartition( true, M, N, k, x, N, out, N, W, 1 ); // $ExpectError
	dkmeansInitRandomPartition( null, M, N, k, x, N, out, N, W, 1 ); // $ExpectError
	dkmeansInitRandomPartition( void 0, M, N, k, x, N, out, N, W, 1 ); // $ExpectError
	dkmeansInitRandomPartition( [], M, N, k, x, N, out, N, W, 1 ); // $ExpectError
	dkmeansInitRandomPartition( {}, M, N, k, x, N, out, N, W, 1 ); // $ExpectError
	dkmeansInitRandomPartition( ( x: number ): number => x, M, N, k, x, N, out, N, W, 1 ); // $ExpectError

	dkmeansInitRandomPartition( 5, M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
	dkmeansInitRandomPartition( true, M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
	dkmeansInitRandomPartition( null, M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
	dkmeansInitRandomPartition( void 0, M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
	dkmeansInitRandomPartition( [], M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
	dkmeansInitRandomPartition( {}, M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
	dkmeansInitRandomPartition( ( x: number ): number => x, M, N, k, x, N, out, N, W, 1, {} ); // $ExpectError
}

